<?php
require __DIR__.'/../includes/payroll/calculation.php';require __DIR__.'/../includes/payroll/templates.php';
function template_check($ok,$message){if(!$ok)throw new RuntimeException($message);}
foreach(pay_template_starters() as $name=>$html){$config=pay_template_config(['template_mode'=>'html','html_template'=>$html]);template_check($config['html_template']!=='',$name);}
foreach(['<script>alert(1)</script>','<img src=x onerror=alert(1)>','<p onclick="alert(1)">x</p>','<p style="background-color:url(https://example.com)">x</p>','<p style="position:fixed">x</p>','<iframe src="https://example.com"></iframe>'] as $bad){$rejected=false;try{pay_template_clean($bad);}catch(InvalidArgumentException $e){$rejected=true;}template_check($rejected,'Unsafe template accepted: '.$bad);}
foreach([[['name'=>'net_salary','source'=>'text','value'=>'fake']],[['name'=>'custom','source'=>'field','value'=>'password']],[['name'=>'a','source'=>'text','value'=>'x'],['name'=>'a','source'=>'text','value'=>'y']]] as $bad){$rejected=false;try{pay_template_attributes($bad);}catch(InvalidArgumentException $e){$rejected=true;}template_check($rejected,'Invalid attributes accepted');}
$config=pay_template_config(['template_mode'=>'html','html_template'=>'<h1>[employee_name]</h1><p>[net_salary] [office] [basic_pay] [bank_account]</p>[earnings_table]','attributes'=>[['name'=>'office','source'=>'text','value'=>'<script>bad</script> [net_salary]'],['name'=>'basic_pay','source'=>'component','value'=>'BASIC']]]);
$entry=['month'=>'2026-10','payslip_number'=>'PAY-1','gross'=>100000,'deductions'=>0,'net'=>100000];$settings=['payslip'=>$config+['show_bank'=>false],'company'=>['name'=>'Company'],'payroll'=>['currency'=>'INR','currency_position'=>'Before']];$snapshot=['employee'=>['name'=>'<b>A&B</b>'],'bank_last4'=>'9876'];$components=[['code'=>'BASIC','name'=>'Basic','category'=>'Earning','amount'=>100000]];
$html=pay_template_render($entry,$settings,$snapshot,$components);template_check(str_contains($html,'&lt;b&gt;A&amp;B&lt;/b&gt;'),'Employee escaped');template_check(str_contains($html,'&lt;script&gt;bad&lt;/script&gt; [net_salary]'),'Single-pass token substitution');template_check(str_contains($html,'INR 1000.00'),'Minor unit rendering');template_check(!str_contains($html,'9876'),'Bank masking setting');
template_check(str_contains(pay_template_document($html),"default-src 'none'"),'Restrictive document CSP');echo "PASS: payslip templates, starters, safe HTML, attribute validation, snapshot values and privacy.\n";
